WITH filtered AS (SELECT id, sale_date, units, revenue, DATE_ADD(sale_date, 22) AS sale_date_plus_22d FROM store_sales WHERE sale_date > TO_DATE('2023-06-22') AND sale_date < '2024-08-01'), enriched AS (SELECT *, FIRST_VALUE(units, TRUE) OVER w_recent AS first_known_units, SUM(units) OVER (ORDER BY revenue, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_units FROM filtered WINDOW w_recent AS (ORDER BY sale_date_plus_22d, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), filtered_store_sales AS (SELECT *, ROUND(cumulative_units * 0.9, 2) AS cumulative_units_adjusted FROM enriched WHERE first_known_units BETWEEN 16 AND 27), enriched_store_sales AS (SELECT id, sale_date, units, revenue, sale_date_plus_22d, first_known_units, cumulative_units, cumulative_units_adjusted, PERCENT_RANK() OVER (ORDER BY first_known_units NULLS LAST) AS first_known_units_percent_rank, LAST_VALUE(cumulative_units, TRUE) OVER (ORDER BY units, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_cumulative_units, NTILE(3) OVER (ORDER BY first_known_units, id) AS first_known_units_bucket FROM filtered_store_sales) SELECT id, units, first_known_units, cumulative_units, cumulative_units_adjusted, first_known_units_percent_rank, last_known_cumulative_units, first_known_units_bucket FROM enriched_store_sales ORDER BY units DESC NULLS LAST;
